insert into public.questions (id, kind, prompt, options, marks) values ('b491f593-dd9f-51a5-80f7-716702d1fa6c', 'short', 'Explain why mutation is important for evolution even though most mutations are neutral or harmful.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b491f593-dd9f-51a5-80f7-716702d1fa6c', 'Mutation is the original source of new alleles and genetic variation [1]; occasionally a mutation is beneficial, and natural selection can increase its frequency, so species evolve [1].', 'Mutation is the original source of new alleles and genetic variation [1]; occasionally a mutation is beneficial, and natural selection can increase its frequency, so species evolve [1].', '[{"text": "Marking point 1", "any": ["source", "new alleles", "variation"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["natural selection", "beneficial", "advantage", "selected"], "all": [], "marks": 1}]'::jsonb, 'Mutation is the original source of new alleles and genetic variation [1]; occasionally a mutation is beneficial, and natural selection can increase its frequency, so species evolve [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
