insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ee5dbb84-b559-5df6-94e6-5071becda94f', 'Environmental factors such as air pollution or diet [1] alter epigenetic tags such as DNA methylation or histone modification [1]; this changes which genes are expressed and so the phenotype, while the DNA base sequence (genotype) is unchanged [1].', 'Environmental factors such as air pollution or diet [1] alter epigenetic tags such as DNA methylation or histone modification [1]; this changes which genes are expressed and so the phenotype, while the DNA base sequence (genotype) is unchanged [1].', '[{"text": "Marking point 1", "any": ["methyl", "epigenetic tag", "histone"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["pollution", "diet", "smoking", "environment"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["sequence", "genotype", "not changed", "unchanged"], "all": [], "marks": 1}]'::jsonb, 'Environmental factors such as air pollution or diet [1] alter epigenetic tags such as DNA methylation or histone modification [1]; this changes which genes are expressed and so the phenotype, while the DNA base sequence (genotype) is unchanged [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
