insert into public.questions (id, kind, prompt, options, marks) values ('587340ec-6965-5af4-b47f-d998bdcc8df9', 'short', 'Explain why oxygen is described as a by-product of photosynthesis.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('587340ec-6965-5af4-b47f-d998bdcc8df9', 'Water is split to supply the hydrogen (and electrons) needed to reduce CO₂ [1]; the oxygen left over is not needed and is released as a by-product (waste) [1].', 'Water is split to supply the hydrogen (and electrons) needed to reduce CO₂ [1]; the oxygen left over is not needed and is released as a by-product (waste) [1].', '[{"text": "Marking point 1", "any": ["splitting of water", "photolysis", "water is split"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["not needed", "not used", "waste", "released", "hydrogen is needed", "only hydrogen"], "all": [], "marks": 1}]'::jsonb, 'Water is split to supply the hydrogen (and electrons) needed to reduce CO₂ [1]; the oxygen left over is not needed and is released as a by-product (waste) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
