insert into public.questions (id, kind, prompt, options, marks) values ('e8b71986-8a37-546d-9000-b7b75951228e', 'short', 'Identify one controlled variable in a FACE experiment and one limitation of the method.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e8b71986-8a37-546d-9000-b7b75951228e', 'Controlled variable: e.g. the same species and plot size in enriched and control plots [1]. Limitation: wind and weather change the CO₂ concentration and other variables cannot be controlled; it is also very expensive [1].', 'Controlled variable: e.g. the same species and plot size in enriched and control plots [1]. Limitation: wind and weather change the CO₂ concentration and other variables cannot be controlled; it is also very expensive [1].', '[{"text": "Marking point 1", "any": ["species", "same plants", "plot size", "same type", "area", "soil"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["wind", "difficult to control", "expensive", "cost", "weather", "uncontrolled"], "all": [], "marks": 1}]'::jsonb, 'Controlled variable: e.g. the same species and plot size in enriched and control plots [1]. Limitation: wind and weather change the CO₂ concentration and other variables cannot be controlled; it is also very expensive [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
