insert into public.questions (id, kind, prompt, options, marks) values ('e8b71986-8a37-546d-9000-b7b75951228e', 'short', 'Identify one controlled variable in a FACE experiment and one limitation of the method.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e8b71986-8a37-546d-9000-b7b75951228e', 'Controlled variable: e.g. the same species and plot size in enriched and control plots [1]. Limitation: wind and weather change the CO₂ concentration and other variables cannot be controlled; it is also very expensive [1].', 'Controlled variable: e.g. the same species and plot size in enriched and control plots [1]. Limitation: wind and weather change the CO₂ concentration and other variables cannot be controlled; it is also very expensive [1].', '[{"text": "Marking point 1", "any": ["species", "same plants", "plot size", "same type", "area", "soil"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["wind", "difficult to control", "expensive", "cost", "weather", "uncontrolled"], "all": [], "marks": 1}]'::jsonb, 'Controlled variable: e.g. the same species and plot size in enriched and control plots [1]. Limitation: wind and weather change the CO₂ concentration and other variables cannot be controlled; it is also very expensive [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c77b046c-671a-528d-8677-cbb1e3dae003', 'e8b71986-8a37-546d-9000-b7b75951228e', 29);
insert into public.questions (id, kind, prompt, options, marks) values ('6f70897d-6d80-5af9-b5f1-45a43a8a68b9', 'short', 'In a greenhouse, raising CO₂ from 400 to 800 ppm increased tomato yield by 30% in winter but only 5% on very hot summer days. Suggest reasons for the difference.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6f70897d-6d80-5af9-b5f1-45a43a8a68b9', 'In winter, CO₂ was the limiting factor, so adding CO₂ greatly increased photosynthesis and yield [1]; on hot summer days, high temperature limits the rate (enzymes near or above the optimum) [1]; also stomata may close to save water, so extra CO₂ cannot enter / another factor limits [1].', 'In winter, CO₂ was the limiting factor, so adding CO₂ greatly increased photosynthesis and yield [1]; on hot summer days, high temperature limits the rate (enzymes near or above the optimum) [1]; also stomata may close to save water, so extra CO₂ cannot enter / another factor limits [1].', '[{"text": "Marking point 1", "any": ["carbon dioxide was limiting", "limiting in winter"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["too hot", "high temperature", "denature"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["water", "stomata", "light", "other factor"], "all": [], "marks": 1}]'::jsonb, 'In winter, CO₂ was the limiting factor, so adding CO₂ greatly increased photosynthesis and yield [1]; on hot summer days, high temperature limits the rate (enzymes near or above the optimum) [1]; also stomata may close to save water, so extra CO₂ cannot enter / another factor limits [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c77b046c-671a-528d-8677-cbb1e3dae003', '6f70897d-6d80-5af9-b5f1-45a43a8a68b9', 30);
