insert into public.questions (id, kind, prompt, options, marks) values ('0f229fea-1546-5cfc-902b-a529cdc4c94a', 'mcq', 'Aerobic, anaerobic or both (in humans)?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('0f229fea-1546-5cfc-902b-a529cdc4c94a', 2, 'O₂, CO₂ and mitochondria: aerobic. Lactate and 2 ATP: anaerobic. Glucose: both.', 'Both') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', '0f229fea-1546-5cfc-902b-a529cdc4c94a', 6);
insert into public.questions (id, kind, prompt, options, marks) values ('87575d08-220e-5576-8527-947078a5f6f1', 'short', 'Write the word equations for aerobic and for anaerobic respiration in humans.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('87575d08-220e-5576-8527-947078a5f6f1', 'Aerobic: glucose + oxygen → carbon dioxide + water [1]. Anaerobic: glucose → lactate [1].', 'Aerobic: glucose + oxygen → carbon dioxide + water [1]. Anaerobic: glucose → lactate [1].', '[{"text": "Marking point 1", "any": [], "all": ["glucose", "oxygen", "carbon dioxide", "water"], "marks": 1}, {"text": "Marking point 2", "any": ["lactic acid"], "all": [], "marks": 1}]'::jsonb, 'Aerobic: glucose + oxygen → carbon dioxide + water [1]. Anaerobic: glucose → lactate [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', '87575d08-220e-5576-8527-947078a5f6f1', 7);
insert into public.questions (id, kind, prompt, options, marks) values ('3a68b2c3-0ba2-5ef8-bdb9-cc114bc8f2ed', 'short', 'Distinguish between cell respiration and gas exchange.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3a68b2c3-0ba2-5ef8-bdb9-cc114bc8f2ed', 'Cell respiration is a set of chemical reactions inside cells that release energy and make ATP [1]; gas exchange is the diffusion of O₂ and CO₂ across an exchange surface such as the alveoli [1].', 'Cell respiration is a set of chemical reactions inside cells that release energy and make ATP [1]; gas exchange is the diffusion of O₂ and CO₂ across an exchange surface such as the alveoli [1].', '[{"text": "Marking point 1", "any": ["chemical", "inside cells", "atp", "release energy"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["diffusion", "surface", "across"], "all": [], "marks": 1}]'::jsonb, 'Cell respiration is a set of chemical reactions inside cells that release energy and make ATP [1]; gas exchange is the diffusion of O₂ and CO₂ across an exchange surface such as the alveoli [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', '3a68b2c3-0ba2-5ef8-bdb9-cc114bc8f2ed', 8);
insert into public.questions (id, kind, prompt, options, marks) values ('15081fbf-9613-5421-b69a-95dc4cc7d781', 'mcq', 'In a respirometer experiment with germinating peas, the liquid moves 36 mm in 12 minutes. Choose the answers.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('15081fbf-9613-5421-b69a-95dc4cc7d781', 0, '36 ÷ 12 = 3 mm min⁻¹. Soda lime absorbs CO₂, so the change shows O₂ uptake. The liquid moves towards the peas as gas volume falls.', '3 mm min⁻¹') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', '15081fbf-9613-5421-b69a-95dc4cc7d781', 9);
insert into public.questions (id, kind, prompt, options, marks) values ('22a92e40-54b6-520e-ab43-561091d6c3f3', 'short', 'Explain why the coloured liquid in a respirometer moves towards the organisms.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('22a92e40-54b6-520e-ab43-561091d6c3f3', 'The organisms use O₂ in aerobic respiration [1]; the CO₂ they release is absorbed by soda lime/KOH [1]; so the volume of gas (and pressure) in the tube falls, drawing the liquid towards the organisms [1].', 'The organisms use O₂ in aerobic respiration [1]; the CO₂ they release is absorbed by soda lime/KOH [1]; so the volume of gas (and pressure) in the tube falls, drawing the liquid towards the organisms [1].', '[{"text": "Marking point 1", "any": ["o2 used", "take in oxygen", "uptake", "consume oxygen", "use o2", "uses o2", "use oxygen", "uses oxygen", "oxygen is used"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["soda lime", "koh"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["pressure", "volume decreases", "less gas", "volume falls"], "all": [], "marks": 1}]'::jsonb, 'The organisms use O₂ in aerobic respiration [1]; the CO₂ they release is absorbed by soda lime/KOH [1]; so the volume of gas (and pressure) in the tube falls, drawing the liquid towards the organisms [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', '22a92e40-54b6-520e-ab43-561091d6c3f3', 10);
insert into public.questions (id, kind, prompt, options, marks) values ('adf795b1-ebde-56fd-9a40-e8a3bbba75ad', 'mcq', 'Oxygen uptake of germinating seeds was 2.0 mm³ min⁻¹ at 10 °C, 4.1 at 20 °C and 7.9 at 30 °C. Choose the answers.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('adf795b1-ebde-56fd-9a40-e8a3bbba75ad', 0, 'Rate increases with temperature, roughly doubling each 10 °C (2.0 → 4.1 → 7.9). Independent variable: temperature. Dependent variable: oxygen uptake.', 'Increases') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', 'adf795b1-ebde-56fd-9a40-e8a3bbba75ad', 11);
insert into public.questions (id, kind, prompt, options, marks) values ('e75d4342-af1d-5273-ad6a-ab643d8bf54e', 'short', 'Explain why a sprinter''s muscles produce lactate in a 100 m race but not during a slow walk.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e75d4342-af1d-5273-ad6a-ab643d8bf54e', 'During sprinting, oxygen cannot be supplied to the muscles fast enough for aerobic respiration alone [1]; so muscles also respire anaerobically, producing lactate [1]; this releases ATP quickly without oxygen, although the yield per glucose is low [1]. During walking, oxygen supply meets demand, so respiration is aerobic.', 'During sprinting, oxygen cannot be supplied to the muscles fast enough for aerobic respiration alone [1]; so muscles also respire anaerobically, producing lactate [1]; this releases ATP quickly without oxygen, although the yield per glucose is low [1]. During walking, oxygen supply meets demand, so respiration is aerobic.', '[{"text": "Marking point 1", "any": ["insufficient oxygen", "not enough oxygen", "oxygen cannot", "lack of oxygen", "oxygen supply"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["anaerobic"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["fast", "quickly", "rapid", "extra atp", "more atp"], "all": [], "marks": 1}]'::jsonb, 'During sprinting, oxygen cannot be supplied to the muscles fast enough for aerobic respiration alone [1]; so muscles also respire anaerobically, producing lactate [1]; this releases ATP quickly without oxygen, although the yield per glucose is low [1]. During walking, oxygen supply meets demand, so respiration is aerobic.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', 'e75d4342-af1d-5273-ad6a-ab643d8bf54e', 12);
