insert into public.questions (id, kind, prompt, options, marks) values ('083b2d69-0161-5797-b3f8-177e0f8920e5', 'short', 'Explain why converting pyruvate to lactate allows glycolysis to continue in anaerobic conditions.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('083b2d69-0161-5797-b3f8-177e0f8920e5', 'Glycolysis needs NAD to accept hydrogen in its oxidation step [1]; in anaerobic conditions pyruvate accepts the hydrogen from reduced NAD, forming lactate [1]; this regenerates (oxidises) NAD so glycolysis can continue producing 2 ATP per glucose [1].', 'Glycolysis needs NAD to accept hydrogen in its oxidation step [1]; in anaerobic conditions pyruvate accepts the hydrogen from reduced NAD, forming lactate [1]; this regenerates (oxidises) NAD so glycolysis can continue producing 2 ATP per glucose [1].', '[{"text": "Marking point 1", "any": ["regenerate", "nad is regenerated", "nad is reformed"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["accepts hydrogen", "hydrogen to pyruvate"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["glycolysis needs nad", "oxidation step", "nad is required"], "all": [], "marks": 1}]'::jsonb, 'Glycolysis needs NAD to accept hydrogen in its oxidation step [1]; in anaerobic conditions pyruvate accepts the hydrogen from reduced NAD, forming lactate [1]; this regenerates (oxidises) NAD so glycolysis can continue producing 2 ATP per glucose [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', '083b2d69-0161-5797-b3f8-177e0f8920e5', 20);
insert into public.questions (id, kind, prompt, options, marks) values ('771da326-e7d5-5187-a6b8-d7012dcdc451', 'short', 'Compare anaerobic respiration in humans and in yeast.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('771da326-e7d5-5187-a6b8-d7012dcdc451', 'Both use glycolysis to produce pyruvate and a net 2 ATP, regenerating NAD [1]; humans convert pyruvate to lactate, while yeast converts it to ethanol [1]; yeast also releases CO₂, humans do not [1].', 'Both use glycolysis to produce pyruvate and a net 2 ATP, regenerating NAD [1]; humans convert pyruvate to lactate, while yeast converts it to ethanol [1]; yeast also releases CO₂, humans do not [1].', '[{"text": "Marking point 1", "any": ["glycolysis", "same pathway"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ethanol"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["co2"], "all": [], "marks": 1}]'::jsonb, 'Both use glycolysis to produce pyruvate and a net 2 ATP, regenerating NAD [1]; humans convert pyruvate to lactate, while yeast converts it to ethanol [1]; yeast also releases CO₂, humans do not [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
