insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('40d5d031-9774-539b-89e0-0c88b564807a', 'Higher temperature increases enzyme activity, so yeast respires faster [1]; more CO₂ is produced per minute, so the dough rises faster [1].', 'Higher temperature increases enzyme activity, so yeast respires faster [1]; more CO₂ is produced per minute, so the dough rises faster [1].', '[{"text": "Marking point 1", "any": ["enzyme", "faster respiration", "rate of respiration", "respire faster"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["carbon dioxide", "co2", "gas"], "all": [], "marks": 1}]'::jsonb, 'Higher temperature increases enzyme activity, so yeast respires faster [1]; more CO₂ is produced per minute, so the dough rises faster [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
