insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('8182cf30-a023-57f8-96d9-45e9beadc21a', 'Electrons from reduced NAD pass along carriers in the inner membrane, releasing energy [1]; the energy is used to pump protons into the intermembrane space [1]; forming a proton concentration gradient [1]; protons diffuse back into the matrix through ATP synthase, which uses the energy to phosphorylate ADP to ATP [1].', 'Electrons from reduced NAD pass along carriers in the inner membrane, releasing energy [1]; the energy is used to pump protons into the intermembrane space [1]; forming a proton concentration gradient [1]; protons diffuse back into the matrix through ATP synthase, which uses the energy to phosphorylate ADP to ATP [1].', '[{"text": "Marking point 1", "any": ["electron", "electrons"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["protons pumped", "pumped into the intermembrane"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["gradient", "concentration of protons", "high concentration"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["atp synthase", "flow back", "back into the matrix"], "all": [], "marks": 1}]'::jsonb, 'Electrons from reduced NAD pass along carriers in the inner membrane, releasing energy [1]; the energy is used to pump protons into the intermembrane space [1]; forming a proton concentration gradient [1]; protons diffuse back into the matrix through ATP synthase, which uses the energy to phosphorylate ADP to ATP [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', '8182cf30-a023-57f8-96d9-45e9beadc21a', 27);
insert into public.questions (id, kind, prompt, options, marks) values ('4e88347c-7a66-509b-ab52-927da098a858', 'short', 'Explain the role of oxygen in aerobic respiration.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('4e88347c-7a66-509b-ab52-927da098a858', 'Oxygen is the terminal (final) electron acceptor at the end of the electron transport chain [1]; it accepts electrons [1] and protons to form water, which keeps electrons flowing along the chain so ATP production continues [1].', 'Oxygen is the terminal (final) electron acceptor at the end of the electron transport chain [1]; it accepts electrons [1] and protons to form water, which keeps electrons flowing along the chain so ATP production continues [1].', '[{"text": "Marking point 1", "any": ["terminal", "final", "last"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["electron"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["water", "protons", "keeps", "continue", "flow"], "all": [], "marks": 1}]'::jsonb, 'Oxygen is the terminal (final) electron acceptor at the end of the electron transport chain [1]; it accepts electrons [1] and protons to form water, which keeps electrons flowing along the chain so ATP production continues [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('0a5fa622-3d29-5fc5-973f-fbb3018dc1e9', '4e88347c-7a66-509b-ab52-927da098a858', 28);
