insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('15081fbf-9613-5421-b69a-95dc4cc7d781', 0, '36 ÷ 12 = 3 mm min⁻¹. Soda lime absorbs CO₂, so the change shows O₂ uptake. The liquid moves towards the peas as gas volume falls.', '3 mm min⁻¹') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
