insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b22e497e-4b85-5b5f-90fe-fff0bf340a64', 'Respiring muscle produces more CO₂ [1]; CO₂ lowers the affinity of haemoglobin for O₂ (curve shifts right) [1]; so more O₂ dissociates and is released to the muscle where it is needed [1].', 'Respiring muscle produces more CO₂ [1]; CO₂ lowers the affinity of haemoglobin for O₂ (curve shifts right) [1]; so more O₂ dissociates and is released to the muscle where it is needed [1].', '[{"text": "Marking point 1", "any": ["carbon dioxide", "co2"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["lower affinity", "reduces affinity", "less affinity", "affinity falls", "lowers", "lower"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["releases more", "more oxygen", "dissociat", "unload"], "all": [], "marks": 1}]'::jsonb, 'Respiring muscle produces more CO₂ [1]; CO₂ lowers the affinity of haemoglobin for O₂ (curve shifts right) [1]; so more O₂ dissociates and is released to the muscle where it is needed [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
